INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4500960, 647965, 88561, '<td valign="top">Very nice use of background color to complement the colored stones.  I like the cropping of the corners, it really works in this shot.</td>', 'Very nice use of background color to complement the colored stones.  I like the cropping of the corners, it really works in this shot.', '2008-02-20 12:23:25.000000', NULL, 1),
(4500969, 648468, 80912, '<td valign="top">A shot of a t-shirt would be much more interesting if it were on a model (who was perhaps demonstrating the motto?), but even as is, it''s dark and needs more contrast.</td>', 'A shot of a t-shirt would be much more interesting if it were on a model (who was perhaps demonstrating the motto?), but even as is, it''s dark and needs more contrast.', '2008-02-20 12:25:59.000000', NULL, 1),
(4500970, 647065, 88561, '<td valign="top">Well done. Nice DOF, nice natural(?) lighting, very sharp focus, nice contrast.</td>', 'Well done. Nice DOF, nice natural(?) lighting, very sharp focus, nice contrast.', '2008-02-20 12:26:07.000000', NULL, 1),
(4500974, 647943, 80912, '<td valign="top">More of the lenscap on shots?</td>', 'More of the lenscap on shots?', '2008-02-20 12:26:49.000000', NULL, 1),
(4500975, 648848, 88561, '<td valign="top">I''ve never tried toasted PB&amp;J, great idea, 7.</td>', 'I''ve never tried toasted PB&J, great idea, 7.', '2008-02-20 12:26:55.000000', NULL, 1),
(4500977, 647499, 88561, '<td valign="top">I find the lamps on the foreground edges distracting.</td>', 'I find the lamps on the foreground edges distracting.', '2008-02-20 12:28:27.000000', NULL, 1),
(4500979, 648727, 80912, '<td valign="top">If you had taken this slightly earlier (or w/ a longer exposure) so that the flash was unnecessary, it would have been a better shot. Also the fact that the creek is a gash up the middle of the shot is a bit jarring - which could work for some challenges, but not for "Peace"</td>', 'If you had taken this slightly earlier (or w/ a longer exposure) so that the flash was unnecessary, it would have been a better shot. Also the fact that the creek is a gash up the middle of the shot is a bit jarring - which could work for some challenges, but not for "Peace"', '2008-02-20 12:28:44.000000', NULL, 1),
(4500984, 648755, 80912, '<td valign="top">Cropping off the edge of the headstone (actually its base)) on the left ruins this for me.</td>', 'Cropping off the edge of the headstone (actually its base)) on the left ruins this for me.', '2008-02-20 12:30:20.000000', NULL, 1),
(4500990, 647014, 80912, '<td valign="top">It''s just that the tree on the right looks so much like a grasping claw...</td>', 'It''s just that the tree on the right looks so much like a grasping claw...', '2008-02-20 12:32:30.000000', NULL, 1),
(4500992, 646771, 67258, '<td valign="top">Yes, there is something strangely calming about this scene. Pleasing lighting and composition, but I particularly like your use of texture.</td>', 'Yes, there is something strangely calming about this scene. Pleasing lighting and composition, but I particularly like your use of texture.', '2008-02-20 12:33:25.000000', NULL, 1),
(4500995, 648665, 80912, '<td valign="top">The light is beautiful, and it really shows off the textures.</td>', 'The light is beautiful, and it really shows off the textures.', '2008-02-20 12:34:13.000000', NULL, 1),
(4501008, 648320, 67258, '<td valign="top">This works very well for the challenge.  It could be viewed on (at least) two levels - as a representation of death and being finally at peace, the stone bench reminding me of a tombstone, combined with the winter scene and dark looming trees, and then on a more prosaic level, of someone finding a moments peace.  I like it.</td>', 'This works very well for the challenge.  It could be viewed on (at least) two levels - as a representation of death and being finally at peace, the stone bench reminding me of a tombstone, combined with the winter scene and dark looming trees, and then on a more prosaic level, of someone finding a moments peace.  I like it.', '2008-02-20 12:36:38.000000', NULL, 1),
(4501014, 648786, 67258, '<td valign="top">Good mono conversion - the subject and composition work well.</td>', 'Good mono conversion - the subject and composition work well.', '2008-02-20 12:37:21.000000', NULL, 1),
(4501015, 648890, 80912, '<td valign="top">But it''s flapping almost violently! The standard isn''t in focus either.</td>', 'But it''s flapping almost violently! The standard isn''t in focus either.', '2008-02-20 12:37:23.000000', NULL, 1),
(4501020, 647790, 80912, '<td valign="top">A bit too soft for my taste - maybe being closer in to just the first page (and including the candle) would have worked better?</td>', 'A bit too soft for my taste - maybe being closer in to just the first page (and including the candle) would have worked better?', '2008-02-20 12:38:47.000000', NULL, 1),
