(4504325, 649003, 84438, '<td valign="top">Hmmm..  Really nice bird photo.  Peace though?  It just doesn''t say it for me.</td>', 'Hmmm..  Really nice bird photo.  Peace though?  It just doesn''t say it for me.', '2008-02-21 11:58:12.000000', NULL, 1),
(4504329, 648314, 35334, '<td valign="top">fine. I see her as more bored or resigned but I''ll accept peaceful.</td>', 'fine. I see her as more bored or resigned but I''ll accept peaceful.', '2008-02-21 11:58:49.000000', NULL, 1),
(4504331, 648980, 84438, '<td valign="top">Absolutely beautiful.  I haven''t been wowed by landscapes in this challenge, but this one really does it for me.</td>', 'Absolutely beautiful.  I haven''t been wowed by landscapes in this challenge, but this one really does it for me.', '2008-02-21 11:58:55.000000', NULL, 1),
(4504333, 648466, 85102, '<td valign="top">love the idea, not so keen on the execution...</td>', 'love the idea, not so keen on the execution...', '2008-02-21 11:59:17.000000', NULL, 1),
(4504336, 647152, 85102, '<td valign="top">very noisy and over-edited. but nice sunset!</td>', 'very noisy and over-edited. but nice sunset!', '2008-02-21 11:59:50.000000', NULL, 1),
(4504343, 647788, 84438, '<td valign="top">Interesting.  Some sharpening artifacts around the beak (It''s glowing).  <br/> <br/>I don''t see why this bird is tranquil?  Is it in a peaceful setting?  Is it with it''s young?  I have no idea. :(</td>', 'Interesting.  Some sharpening artifacts around the beak (It''s glowing).   I don''t see why this bird is tranquil?  Is it in a peaceful setting?  Is it with it''s young?  I have no idea. :(', '2008-02-21 12:00:47.000000', NULL, 1),
(4504346, 648978, 84438, '<td valign="top">Nice job.  A simple take on this challenge, but fits very well.  It could be a bit sharper I think, but it really is nice.</td>', 'Nice job.  A simple take on this challenge, but fits very well.  It could be a bit sharper I think, but it really is nice.', '2008-02-21 12:01:49.000000', NULL, 1),
(4504348, 648673, 84438, '<td valign="top">Who is? What is?<br/> <br/>In my opinion, with a simple shot of flowers, you have to really knock it out of the park since it''s been done so much..  This one doesn''t do much for me to be honest.</td>', 'Who is? What is? In my opinion, with a simple shot of flowers, you have to really knock it out of the park since it''s been done so much..  This one doesn''t do much for me to be honest.', '2008-02-21 12:03:39.000000', NULL, 1),
(4504350, 647152, 84438, '<td valign="top">Looks like the colours were oversaturated, therefore introducing a lot of noise and artifacting.  Nice colours, but this one just doesn''t do it for me.  Sorry.</td>', 'Looks like the colours were oversaturated, therefore introducing a lot of noise and artifacting.  Nice colours, but this one just doesn''t do it for me.  Sorry.', '2008-02-21 12:04:25.000000', NULL, 1),
(4504389, 648718, 30049, '<td valign="top">It''s eerie how realistic the eyes seem in this photo!  Good luck to you in the challenge.</td>', 'It''s eerie how realistic the eyes seem in this photo!  Good luck to you in the challenge.', '2008-02-21 12:18:14.000000', NULL, 1),
(4504397, 647348, 55956, '<td valign="top">well done the photograph (perhaps only a bit over exposed on the top side) but I can''t see the peace.....</td>', 'well done the photograph (perhaps only a bit over exposed on the top side) but I can''t see the peace.....', '2008-02-21 12:19:04.000000', NULL, 1),
(4504405, 648754, 30049, '<td valign="top">This is interesting.  It''s well focused and maybe a tad oversharpened. The streak in the back/upper-left is from the bowl or dish I take it...gives the image a sense of motion/movement which is cool.  Lighting is a little hot in the extreme highlights of the leaf.  Clever idea.  Good luck in the challenge.</td>', 'This is interesting.  It''s well focused and maybe a tad oversharpened. The streak in the back/upper-left is from the bowl or dish I take it...gives the image a sense of motion/movement which is cool.  Lighting is a little hot in the extreme highlights of the leaf.  Clever idea.  Good luck in the challenge.', '2008-02-21 12:21:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4504410, 648981, 84438, '<td valign="top">Pretty unique.  Not sure what I''ll looking at though..  A dead bird or something?  The tombstone looks a bit like a halloween prop.<br/> <br/>Definately OOTB, and the lighting is very nice.</td>', 'Pretty unique.  Not sure what I''ll looking at though..  A dead bird or something?  The tombstone looks a bit like a halloween prop. Definately OOTB, and the lighting is very nice.', '2008-02-21 12:23:31.000000', NULL, 1),
(4504413, 649004, 30049, '<td valign="top">Ok.  Which Michigander is this?  :-D  St. Joseph river...North pier, yes?<br/> <br/>Great lighting captured here!  Perfect time of day to be there.<br/> <br/>Good luck in the challenge.</td>', 'Ok.  Which Michigander is this?  :-D  St. Joseph river...North pier, yes? Great lighting captured here!  Perfect time of day to be there. Good luck in the challenge.', '2008-02-21 12:24:10.000000', NULL, 1),
(4504415, 648347, 84438, '<td valign="top">Very nice!  I think a picture of flower is pretty cliche in this challenge, but in my opinion you nailed this one.  Nicely done.</td>', 'Very nice!  I think a picture of flower is pretty cliche in this challenge, but in my opinion you nailed this one.  Nicely done.', '2008-02-21 12:24:40.000000', NULL, 1),
(4504420, 647071, 30049, '<td valign="top">I love the scarf.  Her expression is right-on also.  I find the background is distracting, and I really, really wish her face (especially the eyes) was in focus.  Best of luck to you in the challenge.</td>', 'I love the scarf.  Her expression is right-on also.  I find the background is distracting, and I really, really wish her face (especially the eyes) was in focus.  Best of luck to you in the challenge.', '2008-02-21 12:25:32.000000', NULL, 1),
(4504421, 648630, 30049, '<td valign="top">Very zenlike.  Certainly says "Peace" without needing a word.  Well done!</td>', 'Very zenlike.  Certainly says "Peace" without needing a word.  Well done!', '2008-02-21 12:26:22.000000', NULL, 1),
(4504423, 648907, 84438, '<td valign="top">Very nice photo, though I think the composition could be more pleasing.  The lighting from the flash looks a little harsh as well.<br/> <br/>I''m having a thing about titles this challenge for some reason.  This is the only place on earth?  To her?  To everyone?</td>', 'Very nice photo, though I think the composition could be more pleasing.  The lighting from the flash looks a little harsh as well. I''m having a thing about titles this challenge for some reason.  This is the only place on earth?  To her?  To everyone?', '2008-02-21 12:27:23.000000', NULL, 1),
(4504424, 648487, 84438, '<td valign="top">Nice painting with light.</td>', 'Nice painting with light.', '2008-02-21 12:27:36.000000', NULL, 1),
(4504425, 648701, 84438, '<td valign="top">Haha.  Well, it''s unique, I''ll give you that!</td>', 'Haha.  Well, it''s unique, I''ll give you that!', '2008-02-21 12:28:12.000000', NULL, 1),
(4504428, 647210, 30049, '<td valign="top">Absolutely adorable!!!  Good catch.  You did a nice job handling the lighting, getting some fill on the near side to offset/balance the brighter background.</td>', 'Absolutely adorable!!!  Good catch.  You did a nice job handling the lighting, getting some fill on the near side to offset/balance the brighter background.', '2008-02-21 12:28:46.000000', NULL, 1),
(4504429, 649052, 84438, '<td valign="top">Wow.  Striking photo!!  The composition is unique and excellent.  Nicely done!</td>', 'Wow.  Striking photo!!  The composition is unique and excellent.  Nicely done!', '2008-02-21 12:29:14.000000', NULL, 1),
(4504433, 648518, 30049, '<td valign="top">Can''t decide if I like the tight (at the top) composition or not.  With it tight it kind of attaches to the border and makes the image seem like one unit and allows the legs/tentacles (whatever you call them) to grab more attention.  This connection also makes the image feel like a container and as a viewer I''m peering in.  Either way, I think others will make this same item a point of contention.  Could impact your score a little.  All JMO of course.  :-)  Good luck!</td>', 'Can''t decide if I like the tight (at the top) composition or not.  With it tight it kind of attaches to the border and makes the image seem like one unit and allows the legs/tentacles (whatever you call them) to grab more attention.  This connection also makes the image feel like a container and as a viewer I''m peering in.  Either way, I think others will make this same item a point of contention.  Could impact your score a little.  All JMO of course.  :-)  Good luck!', '2008-02-21 12:33:51.000000', NULL, 1),
(4504435, 647943, 69368, '<td valign="top">I have to look a long time... could be a very good pic, but it''s much to dark overall</td>', 'I have to look a long time... could be a very good pic, but it''s much to dark overall', '2008-02-21 12:36:55.000000', NULL, 1),
(4504440, 649048, 30049, '<td valign="top">Clever idea.  The pastiness of the white hand is a distraction and an easy mark for negative hits IMO.  It just doesn''t feel right somehow...  Another nit is the black''s &amp; white''s don''t match.  The white of the Yin/Yang (whatever you call it) is greyish, the bg is yellowish, and the hand is much brighter than the other two.  The black of the Yin/Yang thing is a deeper/truer black than the background area.<br/> <br/>This is a tough concept to pull off, especially in a basic challenge that limits you in tweaking this some in selective areas.<br/> <br/>All of the above is JMO of course.  :-D  Good luck in the challenge.</td>', 'Clever idea.  The pastiness of the white hand is a distraction and an easy mark for negative hits IMO.  It just doesn''t feel right somehow...  Another nit is the black''s & white''s don''t match.  The white of the Yin/Yang (whatever you call it) is greyish, the bg is yellowish, and the hand is much brighter than the other two.  The black of the Yin/Yang thing is a deeper/truer black than the background area. This is a tough concept to pull off, especially in a basic challenge that limits you in tweaking this some in selective areas. All of the above is JMO of course.  :-D  Good luck in the challenge.', '2008-02-21 12:39:15.000000', NULL, 1),
(4504465, 646637, 69368, '<td valign="top">could be much better if the drop was less out of focus</td>', 'could be much better if the drop was less out of focus', '2008-02-21 12:50:32.000000', NULL, 1),
(4504468, 648868, 69368, '<td valign="top">hmmm, sorry, but here is nothing in focus</td>', 'hmmm, sorry, but here is nothing in focus', '2008-02-21 12:51:40.000000', NULL, 1),
(4504592, 647943, 47205, '<td valign="top">Very dark and difficult to see</td>', 'Very dark and difficult to see', '2008-02-21 13:49:18.000000', NULL, 1),
(4504601, 648181, 47205, '<td valign="top">Would have worked better if it were sharper as well as a bigger photo to bring out more details in the shoes IMHO</td>', 'Would have worked better if it were sharper as well as a bigger photo to bring out more details in the shoes IMHO', '2008-02-21 13:51:23.000000', NULL, 1),
(4504612, 648706, 47205, '<td valign="top">Needs to be sharper. Nice idea though, but a less blurred image would have "popped" more IMHO</td>', 'Needs to be sharper. Nice idea though, but a less blurred image would have "popped" more IMHO', '2008-02-21 13:54:06.000000', NULL, 1),
(4504615, 647790, 47205, '<td valign="top">Nice lighting</td>', 'Nice lighting', '2008-02-21 13:54:42.000000', NULL, 1),
(4504652, 648868, 89423, '<td valign="top">This picture look blurry, but it''s intristing, shw doesn''t look like she''s meditating, it looks more like she''s smiling at the camra</td>', 'This picture look blurry, but it''s intristing, shw doesn''t look like she''s meditating, it looks more like she''s smiling at the camra', '2008-02-21 14:08:55.000000', NULL, 1),
(4504654, 648857, 89423, '<td valign="top">That''s a really pretty  picture, but the peacefulness isn''t completely clear</td>', 'That''s a really pretty  picture, but the peacefulness isn''t completely clear', '2008-02-21 14:10:40.000000', NULL, 1),
(4504656, 648981, 89423, '<td valign="top">This is just disturbing, I mean ok, Rest In Peace, but a bunch of random fethers with blood, what is even the animal</td>', 'This is just disturbing, I mean ok, Rest In Peace, but a bunch of random fethers with blood, what is even the animal', '2008-02-21 14:11:25.000000', NULL, 1),
(4504664, 647450, 89423, '<td valign="top">I like this two people getting along and not fighting, defently goes with the peaceful theme. The feeling of the picture is also stringe.</td>', 'I like this two people getting along and not fighting, defently goes with the peaceful theme. The feeling of the picture is also stringe.', '2008-02-21 14:13:03.000000', NULL, 1),
(4504666, 648700, 89423, '<td valign="top">This is a very cute little girl sleeping, and she looks peaceful and undisturbed</td>', 'This is a very cute little girl sleeping, and she looks peaceful and undisturbed', '2008-02-21 14:14:07.000000', NULL, 1),
(4504824, 648933, 89333, '<td valign="top">Very nice idea. I think I''d like to see a bit more of the globe and see the dove a touch brighter.</td>', 'Very nice idea. I think I''d like to see a bit more of the globe and see the dove a touch brighter.', '2008-02-21 15:21:53.000000', NULL, 1),
(4504943, 648880, 35334, '<td valign="top">Nice. I can see where you are coming from but this does not connect strongly to peace for me.</td>', 'Nice. I can see where you are coming from but this does not connect strongly to peace for me.', '2008-02-21 15:52:00.000000', NULL, 1),
(4504954, 648754, 35334, '<td valign="top">Beautiful! It looks like it is being swept into a whirlpool which might not be considered peaceful, but I''ll forgive that.</td>', 'Beautiful! It looks like it is being swept into a whirlpool which might not be considered peaceful, but I''ll forgive that.', '2008-02-21 15:54:19.000000', NULL, 1),
(4504961, 648812, 35334, '<td valign="top">Yes, it is a peaceful morning but it isn''t the kind of image that evokes much feeling of any kind in me.</td>', 'Yes, it is a peaceful morning but it isn''t the kind of image that evokes much feeling of any kind in me.', '2008-02-21 15:56:13.000000', NULL, 1),
(4504970, 647698, 35334, '<td valign="top">very nice--a good reminder of an important part of our history</td>', 'very nice--a good reminder of an important part of our history', '2008-02-21 15:58:21.000000', NULL, 1),
(4504975, 647065, 35334, '<td valign="top">nice but it doesn''t evoke the feeling of peace for me</td>', 'nice but it doesn''t evoke the feeling of peace for me', '2008-02-21 15:59:28.000000', NULL, 1),
(4504983, 647928, 35334, '<td valign="top">Nice image--I like the line of posts. I don''t get a strong feeling of peace from the surf; it is too active and potentially threatening.</td>', 'Nice image--I like the line of posts. I don''t get a strong feeling of peace from the surf; it is too active and potentially threatening.', '2008-02-21 16:01:51.000000', NULL, 1),
(4504987, 648538, 35334, '<td valign="top">Yes!!!  It is snowing here now and I''m glad to have the reminder about spring. I love the contrast between the yellow flower and the green stem/leaf in the background.</td>', 'Yes!!!  It is snowing here now and I''m glad to have the reminder about spring. I love the contrast between the yellow flower and the green stem/leaf in the background.', '2008-02-21 16:04:09.000000', NULL, 1),
(4505039, 648095, 5364, '<td valign="top">Why make this so small?</td>', 'Why make this so small?', '2008-02-21 16:25:53.000000', NULL, 1),
(4505041, 648409, 89423, '<td valign="top">Playing music is a good way to escape, and it''s different for this challenge.</td>', 'Playing music is a good way to escape, and it''s different for this challenge.', '2008-02-21 16:27:03.000000', NULL, 1),
(4505042, 648880, 89423, '<td valign="top">I don''t quite understand how this envolves peace...</td>', 'I don''t quite understand how this envolves peace...', '2008-02-21 16:27:45.000000', NULL, 1),
(4505048, 648963, 89423, '<td valign="top">Everything is a blur</td>', 'Everything is a blur', '2008-02-21 16:30:51.000000', NULL, 1),
(4505053, 648396, 89422, '<td valign="top">If the person were a little less centered, it would be better.</td>', 'If the person were a little less centered, it would be better.', '2008-02-21 16:32:58.000000', NULL, 1),
(4505058, 648673, 89422, '<td valign="top">These flowers have an uncomfortable pale color.</td>', 'These flowers have an uncomfortable pale color.', '2008-02-21 16:34:28.000000', NULL, 1),
(4505059, 648756, 89422, '<td valign="top">It looks more like an evil lair. It does really seem peaceful.</td>', 'It looks more like an evil lair. It does really seem peaceful.', '2008-02-21 16:35:02.000000', NULL, 1),
(4505061, 646830, 89422, '<td valign="top">A little too cliched for my taste.</td>', 'A little too cliched for my taste.', '2008-02-21 16:36:27.000000', NULL, 1),
(4505066, 648868, 89422, '<td valign="top">It is far too grainy, it''s too difficult to ignore the poor quality of the picture.</td>', 'It is far too grainy, it''s too difficult to ignore the poor quality of the picture.', '2008-02-21 16:37:41.000000', NULL, 1),
(4505068, 648150, 89422, '<td valign="top">Interesting idea, but the angle isn''t great. Maybe if the road was a littl bigger in the frame.</td>', 'Interesting idea, but the angle isn''t great. Maybe if the road was a littl bigger in the frame.', '2008-02-21 16:38:32.000000', NULL, 1),
(4505069, 648933, 89422, '<td valign="top">A dove? Try avoiding cliched ideas and going for something more original.</td>', 'A dove? Try avoiding cliched ideas and going for something more original.', '2008-02-21 16:40:45.000000', NULL, 1),
(4505071, 648347, 89422, '<td valign="top">I don''t like the blue for the background, it doesnt fit well with the picture.</td>', 'I don''t like the blue for the background, it doesnt fit well with the picture.', '2008-02-21 16:42:51.000000', NULL, 1),
(4505086, 647885, 89422, '<td valign="top">The angle here is simply uninteresting.</td>', 'The angle here is simply uninteresting.', '2008-02-21 16:45:29.000000', NULL, 1),
(4505088, 648251, 35334, '<td valign="top">All I see on high is an over-exposed cloud and a lens flair. I''m sure this works for people who believe in messages from above but it doesn''t work for me. Sorry.</td>', 'All I see on high is an over-exposed cloud and a lens flair. I''m sure this works for people who believe in messages from above but it doesn''t work for me. Sorry.', '2008-02-21 16:46:16.000000', NULL, 1),
(4505089, 648201, 89422, '<td valign="top">Try moving the camera down and seeing a little of the floor.</td>', 'Try moving the camera down and seeing a little of the floor.', '2008-02-21 16:47:07.000000', NULL, 1),
(4505092, 647539, 35334, '<td valign="top">I''m sure this was a peaceful place when you were there but it does not come through to me.</td>', 'I''m sure this was a peaceful place when you were there but it does not come through to me.', '2008-02-21 16:48:04.000000', NULL, 1),
(4505095, 648985, 89422, '<td valign="top">It is too much of an eye strain trying to read the gravestone.</td>', 'It is too much of an eye strain trying to read the gravestone.', '2008-02-21 16:50:38.000000', NULL, 1),
(4505096, 647800, 89333, '<td valign="top">Very, very nice composition. I really the like the diagonal orientation. I would like to see the white fingers more in focus, especially the index finger.</td>', 'Very, very nice composition. I really the like the diagonal orientation. I would like to see the white fingers more in focus, especially the index finger.', '2008-02-21 16:50:48.000000', NULL, 1),
(4505101, 648630, 89333, '<td valign="top">Very nice feeling to the composition and the exposure is good. I would like to have most (maybe around 75%) of the sky cropped out.</td>', 'Very nice feeling to the composition and the exposure is good. I would like to have most (maybe around 75%) of the sky cropped out.', '2008-02-21 16:52:00.000000', NULL, 1),
(4505105, 648181, 89422, '<td valign="top">It''s just far too boring a picture, and would have been nicer if discarded socks were nearby.</td>', 'It''s just far too boring a picture, and would have been nicer if discarded socks were nearby.', '2008-02-21 16:52:35.000000', NULL, 1),
(4505107, 647152, 35334, '<td valign="top">This is certainly a colorful sunset but it needs something more to add interest and a stronger connection to the peace theme.</td>', 'This is certainly a colorful sunset but it needs something more to add interest and a stronger connection to the peace theme.', '2008-02-21 16:53:11.000000', NULL, 1),
(4505109, 648494, 89422, '<td valign="top">She doesn''t look so at peace at all. It''s difficult to pick up a message of peace from a smile so insignificant.</td>', 'She doesn''t look so at peace at all. It''s difficult to pick up a message of peace from a smile so insignificant.', '2008-02-21 16:53:50.000000', NULL, 1),
(4505111, 648534, 89422, '<td valign="top">Although it''s a cute little pun, the picture still isn''t much for the eye.</td>', 'Although it''s a cute little pun, the picture still isn''t much for the eye.', '2008-02-21 16:54:38.000000', NULL, 1),
(4505114, 648605, 89422, '<td valign="top">A little too overused and cliched, try something original.</td>', 'A little too overused and cliched, try something original.', '2008-02-21 16:55:21.000000', NULL, 1),
(4505116, 648718, 89422, '<td valign="top">This is the 600th grave picture I''ve seen. There has to be some creative minds out there somewhere.</td>', 'This is the 600th grave picture I''ve seen. There has to be some creative minds out there somewhere.', '2008-02-21 16:56:04.000000', NULL, 1),
(4505121, 648639, 89422, '<td valign="top">It is a good picture, but just to unoriginal an idea for the theme.</td>', 'It is a good picture, but just to unoriginal an idea for the theme.', '2008-02-21 16:57:40.000000', NULL, 1),
(4505122, 648391, 35334, '<td valign="top">Lovely. This is one of the most peaceful yoga images I have seen so far.</td>', 'Lovely. This is one of the most peaceful yoga images I have seen so far.', '2008-02-21 16:57:41.000000', NULL, 1),
(4505124, 647450, 35334, '<td valign="top">Very Nice!</td>', 'Very Nice!', '2008-02-21 16:58:21.000000', NULL, 1),
(4505126, 648618, 89422, '<td valign="top">The waves are too insignificant in the picture, try zooming or just getting closer.</td>', 'The waves are too insignificant in the picture, try zooming or just getting closer.', '2008-02-21 16:58:53.000000', NULL, 1),
(4505128, 647800, 35334, '<td valign="top">Very nice. I like the diagonal composition. The color seems a bit off--might be a white-balance problem.</td>', 'Very nice. I like the diagonal composition. The color seems a bit off--might be a white-balance problem.', '2008-02-21 17:00:24.000000', NULL, 1),
(4505130, 647348, 89422, '<td valign="top">Someone mourning is not usually someone at peace.</td>', 'Someone mourning is not usually someone at peace.', '2008-02-21 17:00:50.000000', NULL, 1),
(4505135, 648755, 89422, '<td valign="top">And a boring corner as well, try a more creative perspective.</td>', 'And a boring corner as well, try a more creative perspective.', '2008-02-21 17:01:59.000000', NULL, 1),
(4505141, 646771, 35334, '<td valign="top">This is OK. The first thing I noticed was the texture of the rocks. They don''t look right; maybe over-sharpening is the problem. Has the image been tilted? I would expect the floor to be horizontal. If the image were rotated CCW to make the floor horizontal, the gap would be more strongly tilted. I think that might be better.</td>', 'This is OK. The first thing I noticed was the texture of the rocks. They don''t look right; maybe over-sharpening is the problem. Has the image been tilted? I would expect the floor to be horizontal. If the image were rotated CCW to make the floor horizontal, the gap would be more strongly tilted. I think that might be better.', '2008-02-21 17:07:35.000000', NULL, 1),
(4505149, 648605, 35334, '<td valign="top">Is this the white dove of peace? Even if it is really a white pigeon, the  white color gives it a stronger connection to peace than most of the other bird shots.</td>', 'Is this the white dove of peace? Even if it is really a white pigeon, the  white color gives it a stronger connection to peace than most of the other bird shots.', '2008-02-21 17:10:30.000000', NULL, 1),
(4505154, 648590, 35334, '<td valign="top">This is a very nice peaceful moment in the life of a family. I''d like it better if the woman weren''t partially hidden behind the man.</td>', 'This is a very nice peaceful moment in the life of a family. I''d like it better if the woman weren''t partially hidden behind the man.', '2008-02-21 17:12:12.000000', NULL, 1),
(4505158, 648534, 35334, '<td valign="top">sigh...  it''s a nice picture of hands holding peas but the peas pun just doesn''t make it for me.</td>', 'sigh...  it''s a nice picture of hands holding peas but the peas pun just doesn''t make it for me.', '2008-02-21 17:13:57.000000', NULL, 1),
(4505160, 647762, 35334, '<td valign="top">This might work for Christians who believe in salvation but a guy nailed to a cross does not seem very peaceful to me. Sorry.</td>', 'This might work for Christians who believe in salvation but a guy nailed to a cross does not seem very peaceful to me. Sorry.', '2008-02-21 17:15:30.000000', NULL, 1),
