(4505811, 647210, 90367, '<td valign="top">oo, cool</td>', 'oo, cool', '2008-02-21 22:40:04.000000', NULL, 1),
(4505815, 648706, 35334, '<td valign="top">I don''t get it. It looks like there are three layers, the graffiti-covered desk, the hand with the pink bracelet, and then a plastic sheet with peace symbols on it. What am I missing?</td>', 'I don''t get it. It looks like there are three layers, the graffiti-covered desk, the hand with the pink bracelet, and then a plastic sheet with peace symbols on it. What am I missing?', '2008-02-21 22:41:46.000000', NULL, 1),
(4505818, 648785, 35334, '<td valign="top">I''m not sure what the kid is doing but it doesn''t look to me like he is hoping for a peaceful future.</td>', 'I''m not sure what the kid is doing but it doesn''t look to me like he is hoping for a peaceful future.', '2008-02-21 22:43:32.000000', NULL, 1),
(4505824, 647943, 71244, '<td valign="top">This looks like a lovely photo, however it is really too dark to appreciate it.</td>', 'This looks like a lovely photo, however it is really too dark to appreciate it.', '2008-02-21 22:45:50.000000', NULL, 1),
(4505848, 648673, 47205, '<td valign="top">I like the colors as well as the details in the petals. Maybe a touch blown in the highlights, but still very well composed.</td>', 'I like the colors as well as the details in the petals. Maybe a touch blown in the highlights, but still very well composed.', '2008-02-21 23:01:33.000000', NULL, 1),
(4505851, 648658, 47205, '<td valign="top">The crusty bits remind me of when my kids were little. Nice desat and love the little reflects in the eyes.</td>', 'The crusty bits remind me of when my kids were little. Nice desat and love the little reflects in the eyes.', '2008-02-21 23:03:42.000000', NULL, 1),
(4505854, 648901, 47205, '<td valign="top">I like the dividing line of shade and light.</td>', 'I like the dividing line of shade and light.', '2008-02-21 23:05:34.000000', NULL, 1),
(4505857, 649009, 47205, '<td valign="top">Would have like a bit more sharpness in their "love bond", maybe not so much gain. Banana''s rock though :-)</td>', 'Would have like a bit more sharpness in their "love bond", maybe not so much gain. Banana''s rock though :-)', '2008-02-21 23:07:23.000000', NULL, 1),
(4505862, 648727, 47205, '<td valign="top">IMHO if you could have waited until the light was higher in the sky, maybe more towards sunset or late afternoon, the contrasts in this shot would have been so much better.</td>', 'IMHO if you could have waited until the light was higher in the sky, maybe more towards sunset or late afternoon, the contrasts in this shot would have been so much better.', '2008-02-21 23:11:02.000000', NULL, 1),
(4505866, 648920, 47205, '<td valign="top">Nice contrasts, nice colors in the flowers and the reflection works well here. Well done</td>', 'Nice contrasts, nice colors in the flowers and the reflection works well here. Well done', '2008-02-21 23:11:59.000000', NULL, 1),
(4505869, 649003, 47205, '<td valign="top">Wonderful colors, details. Nice capture</td>', 'Wonderful colors, details. Nice capture', '2008-02-21 23:12:35.000000', NULL, 1),
(4505872, 649010, 35334, '<td valign="top">I don''t know very much about Hindu deities but I think this may be Kali with a garland of human skulls around her neck. Or it could be Shiva Nataraja, god of destruction. In any case, the little I know is enough to keep me from taking a sculpture like this as symbolizing peace. That said, your image is a very nice representation of the sculpture.</td>', 'I don''t know very much about Hindu deities but I think this may be Kali with a garland of human skulls around her neck. Or it could be Shiva Nataraja, god of destruction. In any case, the little I know is enough to keep me from taking a sculpture like this as symbolizing peace. That said, your image is a very nice representation of the sculpture.', '2008-02-21 23:15:21.000000', NULL, 1),
(4505873, 648812, 47205, '<td valign="top">Seems very flat. I like the shot, the composition, but me, I love color and a bit more pop</td>', 'Seems very flat. I like the shot, the composition, but me, I love color and a bit more pop', '2008-02-21 23:15:49.000000', NULL, 1),
(4505876, 648639, 35334, '<td valign="top">Fine</td>', 'Fine', '2008-02-21 23:16:02.000000', NULL, 1),
(4505879, 648108, 47205, '<td valign="top">I love landscapes and I like this. My only issues would be a lack of contrast within the mountains somehow, and the one dust spot in the blue just above the cloud layer left</td>', 'I love landscapes and I like this. My only issues would be a lack of contrast within the mountains somehow, and the one dust spot in the blue just above the cloud layer left', '2008-02-21 23:18:07.000000', NULL, 1),
(4505882, 649052, 35334, '<td valign="top">And with the light came conflict. This is a nice image but it does not evoke peace for me.</td>', 'And with the light came conflict. This is a nice image but it does not evoke peace for me.', '2008-02-21 23:18:29.000000', NULL, 1),
(4505883, 648857, 47205, '<td valign="top">Very nice. I like the detail in the grass bloom a lot</td>', 'Very nice. I like the detail in the grass bloom a lot', '2008-02-21 23:19:13.000000', NULL, 1),
(4505899, 648468, 35334, '<td valign="top">I certainly agree that love knows no colors. The shirt is faded and the colors are washed out. Are you trying to say that this was an old problem that has been solved in the 21st century?</td>', 'I certainly agree that love knows no colors. The shirt is faded and the colors are washed out. Are you trying to say that this was an old problem that has been solved in the 21st century?', '2008-02-21 23:25:46.000000', NULL, 1),
(4505901, 648804, 35334, '<td valign="top">nice</td>', 'nice', '2008-02-21 23:26:10.000000', NULL, 1),
(4505911, 648698, 35334, '<td valign="top">I passed on this image the first time I looked at it. I didn''t like it but I couldn''t say why. I think it is the harsh lighting and garish colors that turn me off. I do understand that these aspect were probably deliberate on your part to create a bright, vivid image, but they just don''t work for me.</td>', 'I passed on this image the first time I looked at it. I didn''t like it but I couldn''t say why. I think it is the harsh lighting and garish colors that turn me off. I do understand that these aspect were probably deliberate on your part to create a bright, vivid image, but they just don''t work for me.', '2008-02-21 23:30:33.000000', NULL, 1),
(4505916, 648967, 35334, '<td valign="top">I like the reflections in the water; it is certainly quiet and still.</td>', 'I like the reflections in the water; it is certainly quiet and still.', '2008-02-21 23:32:46.000000', NULL, 1),
(4505922, 648181, 35334, '<td valign="top">I understand where you are coming from--you get a feeling of peace when you get home and kick off your shoes. But this does not come across to me from the image. There is also a lot that could be done to improve the image but I''m assuming that others will give you tips about this.</td>', 'I understand where you are coming from--you get a feeling of peace when you get home and kick off your shoes. But this does not come across to me from the image. There is also a lot that could be done to improve the image but I''m assuming that others will give you tips about this.', '2008-02-21 23:36:16.000000', NULL, 1),
(4505926, 648623, 35334, '<td valign="top">A very nice peaceful moment in a hectic day.</td>', 'A very nice peaceful moment in a hectic day.', '2008-02-21 23:37:23.000000', NULL, 1),
(4505928, 648346, 35334, '<td valign="top">It is certainly quiet and still.</td>', 'It is certainly quiet and still.', '2008-02-21 23:38:31.000000', NULL, 1),
(4505932, 648933, 35334, '<td valign="top">Africa is certainly where peace is needed!</td>', 'Africa is certainly where peace is needed!', '2008-02-21 23:39:47.000000', NULL, 1),
(4505936, 648146, 35334, '<td valign="top">I really don''t get a feeling of peace from this; he looks like he is ready to pounce on some prey. But it is a very nice shot.</td>', 'I really don''t get a feeling of peace from this; he looks like he is ready to pounce on some prey. But it is a very nice shot.', '2008-02-21 23:42:15.000000', NULL, 1),
(4505945, 648658, 35334, '<td valign="top">Why did you use selective desat on this? To me it just looks weird to have color in the pacifier and a little in the eyes. You''ve lost the skin tones that would make the baby look more alive.</td>', 'Why did you use selective desat on this? To me it just looks weird to have color in the pacifier and a little in the eyes. You''ve lost the skin tones that would make the baby look more alive.', '2008-02-21 23:47:21.000000', NULL, 1),
(4505951, 648361, 35334, '<td valign="top">This must have taken a lot of work to set up, but it is just way too gimmicky for me.</td>', 'This must have taken a lot of work to set up, but it is just way too gimmicky for me.', '2008-02-21 23:48:51.000000', NULL, 1),
(4505957, 648640, 35334, '<td valign="top">I''m having a hard time telling what is going on here. Is the animal sleeping or digging in the sand? I wish I could see more of the side that is in shadow.</td>', 'I''m having a hard time telling what is going on here. Is the animal sleeping or digging in the sand? I wish I could see more of the side that is in shadow.', '2008-02-21 23:53:25.000000', NULL, 1),
(4505969, 648890, 23002, '<td valign="top">Hmmm.  I bet this is getting some really entertaining comments, and I will leave it at that. :)</td>', 'Hmmm.  I bet this is getting some really entertaining comments, and I will leave it at that. :)', '2008-02-21 23:59:23.000000', NULL, 1),
(4505972, 648618, 35334, '<td valign="top">yes, a peaceful beach. I see surf rather than tides but that is a quibble.</td>', 'yes, a peaceful beach. I see surf rather than tides but that is a quibble.', '2008-02-22 00:00:39.000000', NULL, 1),
(4505973, 649048, 35334, '<td valign="top">I love it!</td>', 'I love it!', '2008-02-22 00:00:54.000000', NULL, 1),
(4505978, 648146, 23002, '<td valign="top">How is a zoo bird Zen?  Isn''t the poor thing captive and held hostage, kind of the opposite of peace?</td>', 'How is a zoo bird Zen?  Isn''t the poor thing captive and held hostage, kind of the opposite of peace?', '2008-02-22 00:01:36.000000', NULL, 1),
(4505979, 648833, 23002, '<td valign="top">LOL  very funny and interesting take on this.</td>', 'LOL  very funny and interesting take on this.', '2008-02-22 00:02:13.000000', NULL, 1),
(4505984, 648709, 23002, '<td valign="top">Nut Hatch!  nice.</td>', 'Nut Hatch!  nice.', '2008-02-22 00:03:24.000000', NULL, 1),
(4505987, 648308, 23002, '<td valign="top">Where is the bong? LOL</td>', 'Where is the bong? LOL', '2008-02-22 00:04:03.000000', NULL, 1),
(4505992, 648464, 35334, '<td valign="top">I agree with the sentiment but the image could be stronger. She looks a bit like she is holding him off rather than pulling him closer. I''d also like to see more of the man (especially his arms).</td>', 'I agree with the sentiment but the image could be stronger. She looks a bit like she is holding him off rather than pulling him closer. I''d also like to see more of the man (especially his arms).', '2008-02-22 00:06:00.000000', NULL, 1),
(4505996, 648923, 35334, '<td valign="top">Yes, it is a peace symbol but what is it doing in tape? I think there is a story here but you aren''t giving any clues.</td>', 'Yes, it is a peace symbol but what is it doing in tape? I think there is a story here but you aren''t giving any clues.', '2008-02-22 00:07:21.000000', NULL, 1),
(4506101, 648417, 69407, '<td valign="top">Great concept and lovely colors! I''m not entirely sure about the composition, though.</td>', 'Great concept and lovely colors! I''m not entirely sure about the composition, though.', '2008-02-22 01:15:47.000000', NULL, 1),
(4506102, 647911, 69407, '<td valign="top">Beautiful capture!</td>', 'Beautiful capture!', '2008-02-22 01:16:05.000000', NULL, 1),
(4506108, 648494, 69407, '<td valign="top">I love this concept! It may have been improved a bit by simplifying the background - having something out the windows other than white light.</td>', 'I love this concept! It may have been improved a bit by simplifying the background - having something out the windows other than white light.', '2008-02-22 01:17:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4506110, 648383, 69407, '<td valign="top">Beautiful... I love the off-center composition!</td>', 'Beautiful... I love the off-center composition!', '2008-02-22 01:18:11.000000', NULL, 1),
(4506111, 647874, 69407, '<td valign="top">This is brilliant... I can''t believe you captured this!</td>', 'This is brilliant... I can''t believe you captured this!', '2008-02-22 01:18:54.000000', NULL, 1),
(4506116, 646893, 69407, '<td valign="top">She almost looks like a doll... beautiful image, though, very striking! I love the cord in front...it''s so out of place!</td>', 'She almost looks like a doll... beautiful image, though, very striking! I love the cord in front...it''s so out of place!', '2008-02-22 01:20:44.000000', NULL, 1),
(4506122, 646750, 69407, '<td valign="top">Wow. I love the greys, the wardrobe, the orange, the expression, the pose, the composition... beautiful, stunning, and perfect!</td>', 'Wow. I love the greys, the wardrobe, the orange, the expression, the pose, the composition... beautiful, stunning, and perfect!', '2008-02-22 01:22:03.000000', NULL, 1),
(4506123, 648391, 69407, '<td valign="top">This is a beautiful silhouette! A tighter crop may have emphasized the pose more, and the sky seems a little grainy on my monitor (could just be me, though).</td>', 'This is a beautiful silhouette! A tighter crop may have emphasized the pose more, and the sky seems a little grainy on my monitor (could just be me, though).', '2008-02-22 01:23:09.000000', NULL, 1),
(4506206, 648473, 69368, '<td valign="top">ups...there is a date on the pic.</td>', 'ups...there is a date on the pic.', '2008-02-22 02:56:16.000000', NULL, 1),
(4506525, 648361, 89341, '<td valign="top">Nice reflection in the eys</td>', 'Nice reflection in the eys', '2008-02-22 08:29:47.000000', NULL, 1),
(4506528, 647450, 15976, '<td valign="top">Simple but effective, I like it.</td>', 'Simple but effective, I like it.', '2008-02-22 08:31:17.000000', NULL, 1),
