(4506615, 649004, 89341, '<td valign="top">Nice picture</td>', 'Nice picture', '2008-02-22 09:07:58.000000', NULL, 1),
(4506616, 648961, 89341, '<td valign="top">Lovely colours and reflection, really conveys Peace &amp; Tranquility to me</td>', 'Lovely colours and reflection, really conveys Peace & Tranquility to me', '2008-02-22 09:08:30.000000', NULL, 1),
