(4508448, 649004, 70000, '<td valign="top">I would like to see this focus in on the lighthouse a bit more. Right now it is so small it looses some of its impact. Beautiful pastel colors</td>', 'I would like to see this focus in on the lighthouse a bit more. Right now it is so small it looses some of its impact. Beautiful pastel colors', '2008-02-22 20:20:03.000000', NULL, 1),
(4508456, 648973, 70000, '<td valign="top">The large blurred section in the foreground doesn''t work here I think. Blurring large objects in the foreground is really hard to pull off though. I like your concept, but compositionally it could be a lot stronger from either closer in or further away I think</td>', 'The large blurred section in the foreground doesn''t work here I think. Blurring large objects in the foreground is really hard to pull off though. I like your concept, but compositionally it could be a lot stronger from either closer in or further away I think', '2008-02-22 20:22:40.000000', NULL, 1),
(4508465, 647790, 70000, '<td valign="top">Interesting concept, but it doesn''t move me as much as it could. The page being out of focus on the right and having the pages be so bright and kind of yellow tinted makes it look more ordinary</td>', 'Interesting concept, but it doesn''t move me as much as it could. The page being out of focus on the right and having the pages be so bright and kind of yellow tinted makes it look more ordinary', '2008-02-22 20:23:56.000000', NULL, 1),
(4508469, 648945, 70000, '<td valign="top">Pretty morbid view on the challenge, I think this may have had more impact if she didn''t look so alert and awake. Nice composition</td>', 'Pretty morbid view on the challenge, I think this may have had more impact if she didn''t look so alert and awake. Nice composition', '2008-02-22 20:24:40.000000', NULL, 1),
(4508509, 648940, 70000, '<td valign="top">This is a beautiful composition, I love how the swans stand out</td>', 'This is a beautiful composition, I love how the swans stand out', '2008-02-22 21:09:53.000000', NULL, 1),
