(4508573, 647911, 65234, '<td valign="top">Nicely done!  Looks like an actual dove, too.  Like the light and detail and translucence in the wings.  Crop is a little tight on top and maybe a bit too wide on the right, but very nice image overall.</td>', 'Nicely done!  Looks like an actual dove, too.  Like the light and detail and translucence in the wings.  Crop is a little tight on top and maybe a bit too wide on the right, but very nice image overall.', '2008-02-22 21:32:50.000000', NULL, 1),
(4508576, 648709, 65234, '<td valign="top">Looks like a Nuthatch.  I love how its little beak is pointing up.  Nice detail and light, too.  I do tend to find birding peaceful, even joyful when I get a good image of one :-)</td>', 'Looks like a Nuthatch.  I love how its little beak is pointing up.  Nice detail and light, too.  I do tend to find birding peaceful, even joyful when I get a good image of one :-)', '2008-02-22 21:34:56.000000', NULL, 1),
(4508578, 648146, 65234, '<td valign="top">I don''t generally think of raptors as peaceful, but this one appears to be at the moment you captured him.</td>', 'I don''t generally think of raptors as peaceful, but this one appears to be at the moment you captured him.', '2008-02-22 21:35:44.000000', NULL, 1),
(4508580, 648285, 65234, '<td valign="top">Good idea.  I kind of want more light on the playground, but it probably illustrates your point better this way.</td>', 'Good idea.  I kind of want more light on the playground, but it probably illustrates your point better this way.', '2008-02-22 21:37:03.000000', NULL, 1),
(4508597, 648754, 65234, '<td valign="top">Very pretty image.  The smoothness of the water and gentle ripple contribute to the peaceful feeling.</td>', 'Very pretty image.  The smoothness of the water and gentle ripple contribute to the peaceful feeling.', '2008-02-22 21:49:00.000000', NULL, 1),
(4508600, 649004, 65234, '<td valign="top">This is really beautiful.  Lovely soft colors, gentle ripples in the water ... very, very nice.</td>', 'This is really beautiful.  Lovely soft colors, gentle ripples in the water ... very, very nice.', '2008-02-22 21:50:29.000000', NULL, 1),
