(4508975, 647499, 86379, '<td valign="top">wow this is really beautiful. amazing colors!</td>', 'wow this is really beautiful. amazing colors!', '2008-02-23 00:23:03.000000', NULL, 1),
(4508985, 648346, 90663, '<td valign="top">Really pretty landscape shot--the sky may have been less washed out with a polarizer if you had one...I like the balanced composition with equal parts of sky/land/water, adds to the peaceful feel.</td>', 'Really pretty landscape shot--the sky may have been less washed out with a polarizer if you had one...I like the balanced composition with equal parts of sky/land/water, adds to the peaceful feel.', '2008-02-23 00:26:22.000000', NULL, 1),
(4508989, 648314, 90663, '<td valign="top">Nice shot, I never seem to do B&amp;W well...I thought for a minute she had a mouse on her right shoulder until I realized it was the fur trim of her jacket LOL</td>', 'Nice shot, I never seem to do B&W well...I thought for a minute she had a mouse on her right shoulder until I realized it was the fur trim of her jacket LOL', '2008-02-23 00:28:26.000000', NULL, 1),
(4508991, 648623, 90280, '<td valign="top">I like how you captured moment of peace between these newlyweds as most don''t get this chance.</td>', 'I like how you captured moment of peace between these newlyweds as most don''t get this chance.', '2008-02-23 00:30:04.000000', NULL, 1),
(4508992, 648754, 90663, '<td valign="top">Nice tight shot, just the right DOF, I like the blurry ripple effect behind the leaf, nice color too</td>', 'Nice tight shot, just the right DOF, I like the blurry ripple effect behind the leaf, nice color too', '2008-02-23 00:32:29.000000', NULL, 1),
