INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4509006, 648980, 90663, '<td valign="top">Too bad only basic editing allowed here, I bet an HDR merge of two exposures here would have been amazing</td>', 'Too bad only basic editing allowed here, I bet an HDR merge of two exposures here would have been amazing', '2008-02-23 00:47:36.000000', NULL, 1),
(4509010, 648718, 90663, '<td valign="top">I like the tight crop and the subject matter, would have liked to see more sharpness throughout the statue</td>', 'I like the tight crop and the subject matter, would have liked to see more sharpness throughout the statue', '2008-02-23 00:50:10.000000', NULL, 1),
(4509011, 646921, 90663, '<td valign="top">Sweet</td>', 'Sweet', '2008-02-23 00:50:58.000000', NULL, 1),
(4509053, 648804, 90663, '<td valign="top">Very nice angle on this one, sun provides nice texture to the statue</td>', 'Very nice angle on this one, sun provides nice texture to the statue', '2008-02-23 01:04:49.000000', NULL, 1),
(4509062, 647210, 90663, '<td valign="top">Nice framing by the leaves around your subjects!</td>', 'Nice framing by the leaves around your subjects!', '2008-02-23 01:07:31.000000', NULL, 1),
(4509072, 647152, 90663, '<td valign="top">Shot with high ISO? It looks a little noisy...</td>', 'Shot with high ISO? It looks a little noisy...', '2008-02-23 01:11:35.000000', NULL, 1),
(4509132, 648868, 90663, '<td valign="top">Focus issues here, maybe also consider a tighter crop</td>', 'Focus issues here, maybe also consider a tighter crop', '2008-02-23 01:32:04.000000', NULL, 1),
(4509151, 647790, 90663, '<td valign="top">Dark background works well here, nice use of light</td>', 'Dark background works well here, nice use of light', '2008-02-23 01:38:34.000000', NULL, 1),
(4509159, 648251, 90663, '<td valign="top">Nice idea, looks like a good lens too, only a touch of flare</td>', 'Nice idea, looks like a good lens too, only a touch of flare', '2008-02-23 01:42:04.000000', NULL, 1),
(4509163, 649044, 90663, '<td valign="top">Always appreciate people that can incorporate humor into their work, good job</td>', 'Always appreciate people that can incorporate humor into their work, good job', '2008-02-23 01:43:33.000000', NULL, 1),
(4509165, 648871, 90663, '<td valign="top">Nice use of blur, almost looks like fog on dry ice</td>', 'Nice use of blur, almost looks like fog on dry ice', '2008-02-23 01:44:44.000000', NULL, 1),
(4509166, 648150, 90663, '<td valign="top">Nice vivid color, ah I miss spring :)</td>', 'Nice vivid color, ah I miss spring :)', '2008-02-23 01:46:55.000000', NULL, 1),
(4509168, 648308, 90663, '<td valign="top">I think I would have cropped this as a portrait orientation, keeping the guitar in at the left edge and cropping out the stuff on the table to the right.  Technically a good exposure though</td>', 'I think I would have cropped this as a portrait orientation, keeping the guitar in at the left edge and cropping out the stuff on the table to the right.  Technically a good exposure though', '2008-02-23 01:48:59.000000', NULL, 1),
(4509171, 647014, 90663, '<td valign="top">Nice framing effect of the foreground tree on the right, cropping the upper half of the image would have emphasized the colors of the central trees, could have gone either way, OK as is too</td>', 'Nice framing effect of the foreground tree on the right, cropping the upper half of the image would have emphasized the colors of the central trees, could have gone either way, OK as is too', '2008-02-23 01:53:10.000000', NULL, 1),
(4509173, 647348, 90663, '<td valign="top">Would love to know what he''s thinking, nice call on B&amp;W here</td>', 'Would love to know what he''s thinking, nice call on B&W here', '2008-02-23 01:55:08.000000', NULL, 1),
(4509184, 648978, 90663, '<td valign="top">Nice high-key type shot</td>', 'Nice high-key type shot', '2008-02-23 02:05:29.000000', NULL, 1),
(4509187, 648890, 90663, '<td valign="top">Nice use of blur</td>', 'Nice use of blur', '2008-02-23 02:06:31.000000', NULL, 1),
(4509191, 647874, 90663, '<td valign="top">Cool capture of the water droplet hanging from the beak, nice sharpness on the face plumage</td>', 'Cool capture of the water droplet hanging from the beak, nice sharpness on the face plumage', '2008-02-23 02:12:20.000000', NULL, 1),
(4509196, 647911, 90663, '<td valign="top">Nice highlight and shadow detail in the bird, too bad the weather didn''t cooperate, I think he would have been even more striking against a blue sky</td>', 'Nice highlight and shadow detail in the bird, too bad the weather didn''t cooperate, I think he would have been even more striking against a blue sky', '2008-02-23 02:16:19.000000', NULL, 1),
(4509198, 648658, 90663, '<td valign="top">I really like the selective coloration of his eyes, penetrating gaze there!</td>', 'I really like the selective coloration of his eyes, penetrating gaze there!', '2008-02-23 02:18:44.000000', NULL, 1),
(4509199, 647450, 90663, '<td valign="top">Simple composition that very effectively conveys the theme, well done</td>', 'Simple composition that very effectively conveys the theme, well done', '2008-02-23 02:21:48.000000', NULL, 1),
(4509201, 648590, 90663, '<td valign="top">Nice rimlighting effect on the people</td>', 'Nice rimlighting effect on the people', '2008-02-23 02:23:06.000000', NULL, 1),
(4509202, 648320, 90663, '<td valign="top">Nice framing of the subject by the trees</td>', 'Nice framing of the subject by the trees', '2008-02-23 02:24:17.000000', NULL, 1),
(4509240, 648692, 76430, '<td valign="top">It''s certainly peace.  This would have been much more interesting if the fingers were in focus and the background out of focus.</td>', 'It''s certainly peace.  This would have been much more interesting if the fingers were in focus and the background out of focus.', '2008-02-23 03:41:01.000000', NULL, 1),
(4509244, 648961, 76430, '<td valign="top">Beautiful sky and mirror lake.</td>', 'Beautiful sky and mirror lake.', '2008-02-23 03:44:09.000000', NULL, 1),
(4509385, 648605, 32011, '<td valign="top">Excellent photo... my favourite in this challenge.<br/> <br/>Composition is spot on... image is clear... perfect shot for the topic.</td>', 'Excellent photo... my favourite in this challenge. Composition is spot on... image is clear... perfect shot for the topic.', '2008-02-23 06:24:30.000000', NULL, 1),
(4509388, 649048, 32011, '<td valign="top">Nice photo... good idea, well executed technically... only issue I have with it is the hair on the arms tend to by the final focus (for my)... hate to say it, but they''re "distracting".  Other than that minor issue... excellent.</td>', 'Nice photo... good idea, well executed technically... only issue I have with it is the hair on the arms tend to by the final focus (for my)... hate to say it, but they''re "distracting".  Other than that minor issue... excellent.', '2008-02-23 06:28:12.000000', NULL, 1),
(4509389, 648945, 32011, '<td valign="top">While I find this image, or rather, the topic of this image, rather unsettling... disturbing... it <b>IS</b> a good photo.  However, I find the placement of the pills somewhat illogical and something which I''m unable look past when viewing this photo.</td>', 'While I find this image, or rather, the topic of this image, rather unsettling... disturbing... it IS a good photo.  However, I find the placement of the pills somewhat illogical and something which I''m unable look past when viewing this photo.', '2008-02-23 06:33:11.000000', NULL, 1),
(4509390, 647348, 32011, '<td valign="top">So simple, yet so beautiful.  You''ve captured a great expression, and pose.... however, while a good photo for "Peace" it''d probably have done better in a "Boredom" or "Apathy" challenge.  :)</td>', 'So simple, yet so beautiful.  You''ve captured a great expression, and pose.... however, while a good photo for "Peace" it''d probably have done better in a "Boredom" or "Apathy" challenge.  :)', '2008-02-23 06:35:16.000000', NULL, 1),
(4509391, 648754, 32011, '<td valign="top">Great colour... interesting image and use of reflection.  Image is nice and sharp.</td>', 'Great colour... interesting image and use of reflection.  Image is nice and sharp.', '2008-02-23 06:36:28.000000', NULL, 1),
