(4510346, 648923, 90663, '<td valign="top">Not really anything wrong here, but I think it lacks the pop to score well.</td>', 'Not really anything wrong here, but I think it lacks the pop to score well.', '2008-02-23 16:33:37.000000', NULL, 1),
(4510348, 646936, 90663, '<td valign="top">Would like to know how this was set up!</td>', 'Would like to know how this was set up!', '2008-02-23 16:34:29.000000', NULL, 1),
(4510368, 648658, 89546, '<td valign="top">The choice to color the pacifier and the eyes draws your attention to the photo. The colors are very sharp, and the reflection in the eyes is the focal point.</td>', 'The choice to color the pacifier and the eyes draws your attention to the photo. The colors are very sharp, and the reflection in the eyes is the focal point.', '2008-02-23 16:42:37.000000', NULL, 1),
(4510373, 648146, 89546, '<td valign="top">Blurring the background immedeantly draws your attention to the subject. Shot is interseting as it wasnt taken straight on, or straight to the side, the eagles head is tilted.</td>', 'Blurring the background immedeantly draws your attention to the subject. Shot is interseting as it wasnt taken straight on, or straight to the side, the eagles head is tilted.', '2008-02-23 16:43:35.000000', NULL, 1),
(4510377, 647885, 89546, '<td valign="top">The lighting on the left side of the flower causes your eye to look there first. The flowering being sharply in focus is strong, and the background adds nicely as they are the same plants.</td>', 'The lighting on the left side of the flower causes your eye to look there first. The flowering being sharply in focus is strong, and the background adds nicely as they are the same plants.', '2008-02-23 16:44:28.000000', NULL, 1),
(4510381, 648746, 89546, '<td valign="top">My eye immideantly is drawn to the ground in the front of the photo, as it is darker and takes up a lot of space. Cropping the photo would have been a better idea, focusing more on the sky.</td>', 'My eye immideantly is drawn to the ground in the front of the photo, as it is darker and takes up a lot of space. Cropping the photo would have been a better idea, focusing more on the sky.', '2008-02-23 16:46:40.000000', NULL, 1),
(4510382, 648755, 89546, '<td valign="top">The lighting in this photograph makes it interseting. The multiple pieces of the building are well placed in the photograph, as it leads your eye all the way through the photo.</td>', 'The lighting in this photograph makes it interseting. The multiple pieces of the building are well placed in the photograph, as it leads your eye all the way through the photo.', '2008-02-23 16:47:40.000000', NULL, 1),
(4510384, 648890, 89546, '<td valign="top">The flag is too blurry. It pops against the black background, which makes it even more noticably blurry. Try making the subject more in focus next time.</td>', 'The flag is too blurry. It pops against the black background, which makes it even more noticably blurry. Try making the subject more in focus next time.', '2008-02-23 16:48:35.000000', NULL, 1),
(4510386, 648605, 90663, '<td valign="top">Nice job of separating the tonal gradations</td>', 'Nice job of separating the tonal gradations', '2008-02-23 16:48:53.000000', NULL, 1),
(4510389, 648417, 90663, '<td valign="top">I think I would have recomposed this to include all of the baby''s body, perhaps reposition the props?</td>', 'I think I would have recomposed this to include all of the baby''s body, perhaps reposition the props?', '2008-02-23 16:50:10.000000', NULL, 1),
(4510391, 649048, 89546, '<td valign="top">The idea is very strong, and is executed very well. The black and white contrast each other very sharply.</td>', 'The idea is very strong, and is executed very well. The black and white contrast each other very sharply.', '2008-02-23 16:50:35.000000', NULL, 1),
(4510396, 648907, 89546, '<td valign="top">Being so close to the girl, your eye gets stuck there, and dosen''t go all the way to the back of the photo where there is a beautiful sunset. Cropping the picture to just the sunset would have been better.</td>', 'Being so close to the girl, your eye gets stuck there, and dosen''t go all the way to the back of the photo where there is a beautiful sunset. Cropping the picture to just the sunset would have been better.', '2008-02-23 16:51:46.000000', NULL, 1),
(4510397, 649029, 90663, '<td valign="top">I''m scoring this one higher because I like the concept and the perspective</td>', 'I''m scoring this one higher because I like the concept and the perspective', '2008-02-23 16:51:54.000000', NULL, 1),
(4510398, 647788, 89546, '<td valign="top">This picture dosen''t really fit the theme. I dont really think of peace when i see this.</td>', 'This picture dosen''t really fit the theme. I dont really think of peace when i see this.', '2008-02-23 16:52:31.000000', NULL, 1),
(4510403, 648534, 90663, '<td valign="top">Thinking outside the box, you made them look very appetizing!</td>', 'Thinking outside the box, you made them look very appetizing!', '2008-02-23 16:53:20.000000', NULL, 1),
(4510404, 647065, 89546, '<td valign="top">I don''t understand how this is fits the peace theme. The colors are very sharp though.</td>', 'I don''t understand how this is fits the peace theme. The colors are very sharp though.', '2008-02-23 16:53:29.000000', NULL, 1),
(4510407, 648494, 89546, '<td valign="top">The background is very washed out as a result of the sun coming in the window. Shooting at a different time of day might have been better.</td>', 'The background is very washed out as a result of the sun coming in the window. Shooting at a different time of day might have been better.', '2008-02-23 16:54:16.000000', NULL, 1),
(4510408, 646750, 90663, '<td valign="top">May be a bit of a stretch for the theme, but nice monochrome look</td>', 'May be a bit of a stretch for the theme, but nice monochrome look', '2008-02-23 16:54:23.000000', NULL, 1),
(4510411, 648972, 89546, '<td valign="top">The colors in this photograph are very dull, they are all basically the same shade. Shooting in black and white may have been better for this shot, as color doesn''t work at all.</td>', 'The colors in this photograph are very dull, they are all basically the same shade. Shooting in black and white may have been better for this shot, as color doesn''t work at all.', '2008-02-23 16:55:24.000000', NULL, 1),
