(4511719, 648973, 76185, '<td valign="top">I like the idea of this shot, but the backgroud isn''t quite right. Cropping out the top so you don''t see the top of the curtains would help and would also focus attention towards the face/pose.</td>', 'I like the idea of this shot, but the backgroud isn''t quite right. Cropping out the top so you don''t see the top of the curtains would help and would also focus attention towards the face/pose.', '2008-02-24 09:56:16.000000', NULL, 1),
(4511809, 648617, 76185, '<td valign="top">Great Vantage point, nice seasonal feel to it. The coast with the concentric arc pattern and the buildings on the cliff are the more interesting aspects here, perhaps an alternative vantage point could put this to more use as the foreground seems a little plain here by comparison.</td>', 'Great Vantage point, nice seasonal feel to it. The coast with the concentric arc pattern and the buildings on the cliff are the more interesting aspects here, perhaps an alternative vantage point could put this to more use as the foreground seems a little plain here by comparison.', '2008-02-24 10:27:13.000000', NULL, 1),
(4511812, 648746, 76185, '<td valign="top">Great scenery! Foreground darkness is a little off-putting though.</td>', 'Great scenery! Foreground darkness is a little off-putting though.', '2008-02-24 10:27:56.000000', NULL, 1),
